"""Unit tests for the SQLite repositories using a temporary database file."""

import tempfile
import unittest
from pathlib import Path

from spacefractions.question.models import Question, QuestionType
from spacefractions.storage.database import Database
from spacefractions.storage.question_repository import QuestionRepository
from spacefractions.storage.score_repository import ScoreRepository


class StorageTests(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.db = Database(Path(self.tmp.name) / "test.db")
        self.db.init_schema()
        self.question_repo = QuestionRepository(self.db)
        self.score_repo = ScoreRepository(self.db)

    def tearDown(self):
        self.tmp.cleanup()

    def test_question_crud(self):
        question = Question(
            id=0,
            prompt="What is 1/2 + 1/2?",
            options=("1", "1/2", "1/4", "2"),
            correct_answer="1",
            question_type=QuestionType.ADD,
        )
        saved = self.question_repo.save(question)
        self.assertGreater(saved.id, 0)
        self.assertEqual(self.question_repo.count(), 1)
        fetched = self.question_repo.get(saved.id)
        self.assertEqual(fetched.prompt, question.prompt)
        self.assertEqual(fetched.options, question.options)

        updated = Question(id=saved.id, prompt="Updated?", options=("a", "b"), correct_answer="a", question_type=QuestionType.COMPARE)
        self.question_repo.update(updated)
        self.assertEqual(self.question_repo.get(saved.id).prompt, "Updated?")

        self.assertTrue(self.question_repo.delete(saved.id))
        self.assertEqual(self.question_repo.count(), 0)

    def test_scores_ordered(self):
        self.score_repo.save("ann", 3, 5)
        self.score_repo.save("bob", 5, 5)
        self.score_repo.save("cal", 1, 5)
        high = self.score_repo.list_high_scores(10)
        self.assertEqual([entry.player_name for entry in high[:2]], ["bob", "ann"])
        self.assertEqual(high[0].score, 5)


if __name__ == "__main__":
    unittest.main()
